export const CONSULT_FOCI=[{id:'observe',label:'Interpretar achados'},{id:'mechanism',label:'Entender o mecanismo'},{id:'test',label:'Planejar a verificação'},{id:'failure',label:'Simular uma falha'}];
const specialistById=Object.fromEntries(SPECIALISTS.map(s=>[s.id,s]));
export function findSpecialist(id){return specialistById[id]||SPECIALISTS[0];}
export function suggestSpecialists(worldOrDomain=''){
 const v=String(worldOrDomain).toLowerCase();
 const ranked=SPECIALISTS.filter(s=>s.worlds.includes(v));
 if(ranked.length)return [...ranked,...SPECIALISTS.filter(s=>!ranked.includes(s))].slice(0,5);
 const hints=[['leuco|hematol|eosinof|inflama|dress','leucograma'],['hem[oó]lise|l[uú]pus|humoral|autoimune|sorolog|hepatite','humoral'],['hiv|imunodefic|siri|viral','celular'],['complement|neisseria','complemento'],['vacina|imuniza','vacinas'],['transplant|hla|mhc','apresentacao'],['tumor|car-t','imunoterapia'],['mucosa|iga|esofag','mucosas'],['fagocit|innat','inata']];
 const match=hints.find(([pattern])=>new RegExp(pattern,'i').test(v));
 return match?[findSpecialist(match[1]),...SPECIALISTS.filter(s=>s.id!==match[1])].slice(0,5):SPECIALISTS.slice(0,5);
}
export function consultationAdvice({world='',caseTitle='',indicators=[],phase='investigate',specialty='',focus='observe',severity=''}={}){
 const s=findSpecialist(specialty||suggestSpecialists(world)[0].id);
 const texts={observe:s.observation,mechanism:s.mechanism,test:s.verify,failure:s.failure};
 const context=focus==='observe'&&indicators.length?`Considere o achado já disponível: “${String(indicators[0]).slice(0,180)}”.`:
 phase==='triage'&&severity==='alta'?'Antes da interpretação mecanística, reconheça instabilidade e sinais de gravidade.':
 phase==='exams'?'Escolha exames que realmente discriminem hipóteses e registre por que os solicitou.':
 phase==='mechanism'?'Conecte ao menos dois achados independentes ao mecanismo que está propondo.':
 phase==='cascade'?'Ordene primeiro os eventos necessários e depois suas consequências.':
 'Use a observação do caso para formular uma hipótese que possa ser confrontada com novos dados.';
 return {specialty:s.id,heading:`Consultoria · ${s.name}`,focus,caseTitle:String(caseTitle).slice(0,140),body:texts[focus]||texts.observe,context,clinicalQuestion:focus==='test'?'Que observação diferenciaria as hipóteses concorrentes?':focus==='failure'?'Qual consequência você espera quando esta etapa deixa de funcionar?':focus==='mechanism'?'Qual evento molecular ou celular liga os achados à consequência?':'Quais dados são medidos diretamente e quais são inferências?',lab:s.lab};
}
